  "landing.spotlightLabel": "\u751f\u6001\u805a\u7126",
  "landing.spotlightTitle": "\u5728 Hedera \u4e0a\u6784\u5efa\u7684\u6709\u8da3\u9879\u76ee",
  "landing.spotlightSub": "\u771f\u6b63\u7684\u56e2\u961f\u5728\u7f51\u7edc\u4e0a\u6253\u9020\u771f\u6b63\u7684\u4ea7\u54c1\u3002\u503c\u5f97\u4e00\u770b\u3002",
  "landing.neuronDesc": "\u4f26\u6566\u822a\u7a7a\u79d1\u6280\u516c\u53f8,\u5728 Hedera \u4e0a\u8bb0\u5f55\u65e0\u4eba\u673a\u5b9e\u65f6\u98de\u884c\u6570\u636e\u2014\u2014\u6253\u9020\u96f7\u8fbe\u7cfb\u7edf,\u8ba9\u65e0\u4eba\u9a7e\u9a76\u98de\u884c\u5668\u5b89\u5168\u5171\u4eab\u5929\u7a7a\u3002",
  "landing.pharmaDesc": "\u5728 Hedera \u4e0a\u7684 DePIN \u7f51\u7edc,\u8ffd\u8e2a\u836f\u54c1\u4f9b\u5e94\u94fe\u2014\u2014\u4ece\u5de5\u5382\u5230\u60a3\u8005,\u9a8c\u8bc1\u836f\u54c1\u771f\u4f2a\u3002",
  "landing.newLabel": "Web3 \u65b0\u624b\uff1f\u4ece\u8fd9\u91cc\u5f00\u59cb",
  "landing.newTitle": "\u7528\u4eba\u8bdd\u8bb2\u52a0\u5bc6\u8d27\u5e01",
  "landing.newSub": "\u6ca1\u6709\u672f\u8bed\uff0c\u4e0d\u9700\u8981\u91d1\u878d\u5b66\u4f4d\u3002\u5165\u573a\u524d\u9700\u8981\u77e5\u9053\u7684\u4e09\u4ef6\u4e8b\u3002",
  "landing.new1t": "dApp \u5c31\u662f\u5e94\u7528\u2014\u2014\u53ea\u662f\u6ca1\u6709\u4e2d\u95f4\u5546",
  "landing.new1b": "dApp\uff08\u53bb\u4e2d\u5fc3\u5316\u5e94\u7528\uff09\u8fd0\u884c\u5728\u516c\u5171\u7f51\u7edc\u4e0a\uff0c\u800c\u4e0d\u662f\u67d0\u5bb6\u516c\u53f8\u7684\u670d\u52a1\u5668\u4e0a\u3002\u6ca1\u6709\u4eba\u80fd\u51fa\u552e\u4f60\u7684\u6570\u636e\u3001\u5c01\u7981\u4f60\u7684\u8d26\u53f7\u6216\u62bd\u6210 30%\u2014\u2014\u89c4\u5219\u5199\u5728\u4eba\u4eba\u53ef\u89c1\u7684\u4ee3\u7801\u91cc\u3002",
  "landing.new2t": "\u4f60\u7684\u94b1\u5305\u5c31\u662f\u4f60\u7684\u767b\u5f55\u65b9\u5f0f",
  "landing.new2b": "\u6ca1\u6709\u5bc6\u7801\u3001\u6ca1\u6709\u90ae\u7bb1\u3001\u6ca1\u6709\u771f\u5b9e\u59d3\u540d\u3002\u4f60\u7684\u52a0\u5bc6\u94b1\u5305\uff08\u5982 HashPack\uff09\u8f7b\u70b9\u4e00\u4e0b\u5373\u53ef\u8bc1\u660e\u8eab\u4efd\u3002\u4f60\u62e5\u6709\u81ea\u5df1\u7684\u8eab\u4efd\u2014\u2014Voicescape \u4ece\u4e0d\u67e5\u770b\u6216\u5b58\u50a8\u4f60\u7684\u79c1\u94a5\u3002",
  "landing.new3t": "\u4e3a\u4ec0\u4e48\u9009\u62e9 Hedera\uff1a\u82b1\u7684\u662f\u5206\uff0c\u4e0d\u662f\u5143",
  "landing.new3b": "\u5728\u65e7\u533a\u5757\u94fe\u4e0a\u8f6c\u8d26\uff0c\u6709\u65f6\u624b\u7eed\u8d39\u6bd4\u5c0f\u8d39\u672c\u8eab\u8fd8\u8d35\u3002\u5728 Hedera \u4e0a\uff0c\u4ea4\u6613\u51e0\u79d2\u949f\u786e\u8ba4\uff0c\u624b\u7eed\u8d39\u4e0d\u5230\u4e00\u5206\u94b1\u2014\u2014\u6240\u4ee5 1 \u7f8e\u5143\u7684\u5c0f\u8d39\u5b9e\u5b9e\u5728\u5728\u5230\u8d26 1 \u7f8e\u5143\uff08\u4ec5\u6263\u9664\u6211\u4eec 2% \u7684\u5fae\u5c0f\u8d39\u7528\uff09\u3002",
