  "landing.freeRotating": "\u7a7a\u6295\u8f6e\u6362\u4e2d",
  "landing.freeMclarenDesc": "\u8fc8\u51ef\u4f26\u8f66\u961f\u7684\u5b98\u65b9\u6536\u85cf\u54c1\u5e73\u53f0\u8fd0\u884c\u5728 Hedera \u4e0a\u2014\u2014\u5e76\u5411\u8f66\u8ff7\u53d1\u653e\u514d\u8d39\u6570\u5b57\u6536\u85cf\u54c1\u3002",
