  "landing.clarityBody": "\u0905\u092e\u0947\u0930\u093f\u0915\u0940 \u0938\u0940\u0928\u0947\u091f \u092e\u0947\u0902 \u0921\u093f\u091c\u093f\u091f\u0932 \u090f\u0938\u0947\u091f \u092e\u093e\u0930\u094d\u0915\u0947\u091f \u0915\u094d\u0932\u0948\u0930\u093f\u091f\u0940 \u090f\u0915\u094d\u091f \u092a\u0930 \u092a\u0939\u0932\u093e \u092a\u094d\u0930\u0915\u094d\u0930\u093f\u092f\u093e\u0924\u094d\u092e\u0915 \u0935\u094b\u091f \u0939\u094b\u0928\u0947 \u0915\u0940 \u0909\u092e\u094d\u092e\u0940\u0926 \u0939\u0948 \u2014 \u092f\u0939 \u0935\u093f\u0927\u0947\u092f\u0915 \u0905\u092e\u0947\u0930\u093f\u0915\u093e \u092e\u0947\u0902 \u0915\u094d\u0930\u093f\u092a\u094d\u091f\u094b \u0915\u094b \u0938\u094d\u092a\u0937\u094d\u091f \u0915\u093e\u0928\u0942\u0928\u0940 \u0922\u093e\u0902\u091a\u093e \u0926\u0947\u0917\u093e\u0964 \u092f\u0939 \u0905\u092e\u0947\u0930\u093f\u0915\u093e \u092e\u0947\u0902 \u0915\u094d\u0930\u093f\u092a\u094d\u091f\u094b \u0915\u0947 \u0932\u093f\u090f \u0938\u092c\u0938\u0947 \u092e\u0939\u0924\u094d\u0935\u092a\u0942\u0930\u094d\u0923 \u0928\u093f\u092f\u093e\u092e\u0915 \u0915\u094d\u0937\u0923\u094b\u0902 \u092e\u0947\u0902 \u0938\u0947 \u090f\u0915 \u0939\u094b \u0938\u0915\u0924\u093e \u0939\u0948\u0964",
  "landing.clarityNote": "\u0905\u092a\u0947\u0915\u094d\u0937\u093f\u0924 15 \u0938\u093f\u0924\u0902\u092c\u0930 2026 \u00b7 \u092c\u0939\u0938 \u0936\u0941\u0930\u0942 \u0915\u0930\u0928\u0947 \u0939\u0947\u0924\u0941 \u092a\u094d\u0930\u0915\u094d\u0930\u093f\u092f\u093e\u0924\u094d\u092e\u0915 \u0935\u094b\u091f",
