  "landing.clarityLiveBody": "\u0938\u0940\u0928\u0947\u091f \u0915\u093e \u0915\u094d\u0932\u0948\u0930\u093f\u091f\u0940 \u090f\u0915\u094d\u091f \u092a\u094d\u0930\u0915\u094d\u0930\u093f\u092f\u093e\u0924\u094d\u092e\u0915 \u0935\u094b\u091f \u092c\u0938 \u0939\u094b\u0928\u0947 \u0935\u093e\u0932\u093e \u0939\u0948\u0964 \u0928\u0924\u0940\u091c\u0947 \u0915\u0947 \u0932\u093f\u090f \u0928\u0940\u091a\u0947 \u0915\u0940 \u0938\u0941\u0930\u094d\u0916\u093f\u092f\u093e\u0902 \u0926\u0947\u0916\u0947\u0902 \u2014 \u092f\u0939 \u0939\u0930 Voicescape \u0915\u094d\u0930\u093f\u090f\u091f\u0930 \u0915\u0947 \u092d\u0935\u093f\u0937\u094d\u092f \u0915\u094b \u0906\u0915\u093e\u0930 \u0926\u0947\u0917\u093e\u0964",
  "landing.halvingLabel": "\u0939\u0948\u0935\u093f\u0902\u0917 \u0915\u093e\u0909\u0902\u091f\u0921\u093e\u0909\u0928",
  "landing.halvingTitle": "\u0905\u0917\u0932\u0940 \u0939\u0948\u0935\u093f\u0902\u0917",
  "landing.halvingSub": "\u092c\u093f\u091f\u0915\u0949\u0907\u0928 \u0914\u0930 \u0932\u093e\u0907\u091f\u0915\u0949\u0907\u0928 \u0932\u0917\u092d\u0917 \u0939\u0930 \u091a\u093e\u0930 \u0938\u093e\u0932 \u092e\u0947\u0902 \u092c\u094d\u0932\u0949\u0915 \u0930\u093f\u0935\u0949\u0930\u094d\u0921 \u0906\u0927\u093e \u0915\u0930 \u0926\u0947\u0924\u0947 \u0939\u0948\u0902 \u2014 \u0926\u094b\u0928\u094b\u0902 \u0915\u093e\u0909\u0902\u091f\u0921\u093e\u0909\u0928 \u0928\u0940\u091a\u0947 \u0932\u093e\u0907\u0935 \u0939\u0948\u0902\u0964",
