  "landing.showHashpack": "\u0905\u0927\u093f\u0915\u093e\u0902\u0936 Voicescape \u0915\u094d\u0930\u093f\u090f\u091f\u0930\u094d\u0938 \u0915\u093e \u0935\u0949\u0932\u0947\u091f",
  "landing.showSaucer": "Hedera \u0915\u093e \u0905\u0917\u094d\u0930\u0923\u0940 \u0935\u093f\u0915\u0947\u0902\u0926\u094d\u0930\u0940\u0915\u0943\u0924 \u090f\u0915\u094d\u0938\u091a\u0947\u0902\u091c",
