  // Brand pass (2026-09-15, Brandon-approved mockup)
  "brand.eyebrow": "यूज़र / AI के बनाए blockpages",
  "landing.brandH1a": "इंटरनेट में आपका अपना कोना।",
  "landing.brandH1b": "आप सब कुछ का 98% रखते हैं।",
  "landing.brandSub": "अपना blockpage बनाएं। जब कोई आपको टिप देता है, वह सीधे आपके वॉलेट में आती है — कोई बिचौलिया नहीं, कोई प्लेटफॉर्म पहले अपना हिस्सा नहीं काटता। यह आपका है।",
  "landing.brandBuildCta": "अपना blockpage बनाएं",
  "landing.brandExploreCta": "एक्सप्लोर करें",
  "landing.splitExplain": "जिसे आप टिप देते हैं, उसे 98% मिलता है। 2% से काम चलता है। हर बार ऑन-चेन — आप खुद देख सकते हैं।",
  "landing.pulsePages": "चेन पर blockpages",
  "landing.pulseTips": "टिप्स सेटल हुईं",
  "landing.pulseShare": "हर टिप का क्रिएटर तक",
  "landing.liveBadge": "LIVE",
  "landing.headlinesLabel": "Hedera की सुर्खियां",
  "landing.lobbyLabel": "लॉबी में चल रहा है",
  "landing.featuredLabel": "चुनिंदा blockpage",
  "landing.featuredSub": "Voicescape के चुनिंदा पेज — फ़ॉलोअर और बैज के हिसाब से लाइव रैंकिंग।",
  "landing.featuredFollowers": "फ़ॉलोअर",
  "landing.featuredBadges": "बैज",
  "landing.founderQuote": "“मैंने इसे सिर्फ़ एक फोन से बनाना शुरू किया, एक कोना करके। अगर यह एक भी इंसान की ज़िंदगी बदल दे, तो हम कामयाब हुए।”",
  "landing.founderQuoteBy": "— ब्रैंडन, संस्थापक",
  "landing.grassroots": "खुले में बनाया · ग्रासरूट, कॉर्पोरेट नहीं",
  "landing.mainnetTag": "Hedera मेननेट",
  "onboard.eyebrow": "यहां से शुरू करें",
  "onboard.title": "क्रिप्टो — इंसान की भाषा में",
  "onboard.lede": "सिर्फ़ चार छोटे कदम। न व्हाइटपेपर, न होमवर्क — बस उतना ही जितना इसे अपना बनाने के लिए चाहिए।",
  "onboard.s1t": "आपका वॉलेट ही आपकी पहचान है",
  "onboard.s1b": "एक वॉलेट, एक आप। एक बार साइन इन करें और आप यहां हर जगह पहचाने जाएंगे — न पासवर्ड, न संभालने के लिए अकाउंट।",
  "onboard.s2t": "आपका blockpage ही आपका कोना है",
  "onboard.s2b": "इंटरनेट का आपका अपना छोटा हिस्सा। अपने लिंक, अपना संगीत, अपनी कहानी इस पर डालें — ऐसा बनाएं जैसे आप हों।",
  "onboard.s3t": "टिप्स सीधे आपके वॉलेट में आती हैं — 98% आप रखते हैं",
  "onboard.s3b": "कोई आपको 5 टिप देता है, आपको 4.9 मिलते हैं। दो प्रतिशत से काम चलता है। बस यही पूरा सौदा है, ऑन-चेन सेटल होता है।",
  "onboard.s4t": "कमांड आपके हाथ में",
  "onboard.s4b": "आपका वॉलेट, आपका blockpage, आपका पैसा। बीच में कोई नहीं बैठा आपके लिए फ़ैसले लेने वाला।",
  "onboard.back": "पीछे",
  "onboard.keepGoing": "आगे बढ़ें",
  "builder.brandEyebrow": "बिल्डर",
  "builder.brandTitle": "इसे अपना बनाएं",
  "builder.brandLede": "एक शुरुआती लुक चुनें, अपनी चीज़ें डालें, पब्लिश दबाएं। बाद में सब कुछ बदल सकते हैं — जब तक आप न कहें, कुछ भी स्थायी नहीं है।",
  "builder.publishHelper": "आपका वॉलेट एक बार साइन करेगा — जब तक आप अप्रूव न करें, कुछ भी नहीं हिलेगा। कभी भी एडिट या अनपब्लिश कर सकते हैं।",
  "page.tipJarLabel": "टिप जार",
  "page.tippedSoFar": "{total} HBAR टिप अब तक",
  "page.tipSplitExplain": "जब आप {name} को टिप देते हैं, वे 98% रखते हैं — सीधे उनके वॉलेट में। बाकी 2% से Voicescape चलता है। हर बार ऑन-चेन सेटल, हमेशा।",
  "page.tipCta": "{name} को टिप दें",
  "tip.titleFor": "{name} को टिप दें",
  "tip.subtitle": "सीधे उनके वॉलेट में जाती है",
  "tip.youSend": "आप भेजते हैं",
  "tip.creatorGets": "{name} को मिलता है (98%)",
  "tip.treasuryGets": "ट्रेज़री को मिलता है (2%)",
  "tip.networkFee": "नेटवर्क फीस ≈ {fee} HBAR (Hedera को जाती है, Voicescape को नहीं)",
  "tip.breakdownNote": "{hbar} HBAR अंदर → {toCreator} {name} को, {fee} से Voicescape चलता है। कुछ भी छिपा नहीं।",
  "tip.approveNote": "आप इसे अपने वॉलेट में अप्रूव करेंगे —\nजब तक आप न कहें, कुछ भी नहीं हिलेगा।",
  "tip.confirmCta": "टिप भेजें ${amount}",
  "tip.confirmCtaHbar": "टिप भेजें {amount} HBAR",
  "buddy.greeting": "हे, मैं Buddy हूं। मैं कोई भी blockpage देख सकता हूं, बता सकता हूं कोई टिप आई या नहीं, या दिखा सकता हूं ट्रेज़री कैसी चल रही है। क्या चल रहा है?",
  "buddy.tagline": "कुछ भी पूछें — मैं चेन देखता हूं",
  "buddy.inputPlaceholder": "Buddy से पूछें…",

  // One-time claim congrats (2026-09-15)
  "congrats.title": "आपका blockpage लाइव हो गया!",
