  "landing.heroBody": "あなたのストーリー、リンク、音楽を、真にあなたのものになる1ページに——どのプラットフォームにも削除できず、大きな手数料も取られません。ファンはウォレットから直接投げ銭し、数秒で決済。1ドルのうち98¢があなたに届きます。",
