  "landing.feeCompare": "$1の投げ銭はカード手数料で約$0.33失われます。Hederaなら同じ投げ銭の移動コストは約$0.0001 — 1ドルのうち98セントがクリエイターに届きます。$0.01の投げ銭もそのまま残り、数秒で確定、98/2分割はオンチェーンで誰でも検証できます。",
