  "landing.trackS3": "詳細をすべて確認できます: 送信者、受信者、金額、そして同じトランザクション内での98/2分割。",
  "landing.trackS4": "アカウント — blockpageオーナーのウォレットなど — を調べれば、そのすべての取引を一か所で見られます。",
