  "landing.neuronDesc": "Công ty công nghệ hàng không London ghi dữ liệu bay drone theo thời gian thực trên Hedera — hệ thống radar để máy bay không người lái chia sẻ bầu trời an toàn.",
  "landing.pharmaDesc": "Mạng DePIN truy xuất chuỗi cung ứng thuốc trên Hedera — xác minh thuốc chính hãng từ nhà máy tới bệnh nhân.",
