  "landing.new2t": "Ví là đăng nhập",
  "landing.new2b": "Không mật khẩu, không email, không tên thật. Ví crypto (như HashPack) chứng minh bạn là bạn chỉ với một chạm. Danh tính thuộc về bạn — Voicescape không bao giờ thấy hay lưu private key của bạn.",
  "landing.new3t": "Vì sao Hedera: tính bằng xu, không phải đô",
  "landing.new3b": "Gửi tip trên blockchain cũ có khi tốn hơn cả tiền tip. Trên Hedera, giao dịch chốt trong vài giây với phí chỉ một phần xu — tip $1 đến nơi vẫn là $1 (trừ 2% nhỏ của chúng tôi).",
