  "landing.clarityTitle": "Pagboto ng Senado sa Clarity Act",
  "landing.clarityBody": "Inaasahang magsasagawa ang Senado ng U.S. ng unang procedural vote sa Digital Asset Market Clarity Act — ang panukalang batas na sa wakas ay magbibigay sa crypto ng malinaw na legal na balangkas sa Amerika. Maaaring ito ang isa sa pinakamahalagang sandali ng regulasyon ng U.S. para sa crypto.",
