  "landing.neuronDesc": "Teknolohiyang pang-abyasyon mula London na nagla-log ng real-time na datos ng paglipad ng drone sa Hedera — sistemang radar para ligtas na magbahagi ng kalangitan ang mga pilotless na sasakyang panghimpapawid.",
  "landing.pharmaDesc": "DePIN network na sumusubaybay sa supply chain ng gamot sa Hedera — bine-verify ang pagiging tunay ng gamot mula pabrika hanggang pasyente.",
  "landing.newLabel": "Bago sa Web3? Magsimula rito",
  "landing.newTitle": "Crypto, ipinaliwanag nang makatao",
  "landing.newSub": "Walang jargon, hindi kailangan ng finance degree. Tatlong bagay na dapat malaman bago sumabak.",
  "landing.new1t": "Ang dApp ay app lang — walang middleman",
  "landing.new1b": "Ang dApp (decentralized app) ay tumatakbo sa pampublikong network sa halip na sa server ng isang kumpanya. Walang makakapagbenta ng datos mo, makakapag-shut off ng account mo, o makakakuha ng 30% — ang mga patakaran ay nakasulat sa code na nakikita ng lahat.",
  "landing.new2t": "Ang wallet mo ang login mo",
  "landing.new2b": "Walang password, walang email, walang tunay na pangalan. Pinapatunayan ng crypto wallet mo (tulad ng HashPack) na ikaw ito sa isang tap. Sa iyo ang pagkakakilanlan mo — hindi kailanman nakikita o iniimbak ng Voicescape ang private keys mo.",
  "landing.new3t": "Bakit Hedera: sentimo, hindi dolyar",
  "landing.new3b": "Ang pagpapadala ng tip sa lumang blockchain ay maaaring mas mahal pa kaysa sa tip mismo. Sa Hedera, naaayos ang mga transaksyon sa ilang segundo sa halagang bahagi lang ng sentimo — kaya ang $1 na tip ay dumarating bilang $1 (minus ang maliit naming 2%).",
